package com.zz.babyfeeding.common.util;

import java.util.Locale;
import java.util.UUID;
import java.util.regex.Pattern;

/**
 * UUID validation. Domain ids are UUID v4, lower-case; the device id is an
 * anonymous UUID v4 generated by the client.
 */
public final class UuidUtils {

    private static final Pattern UUID_V4 = Pattern.compile(
            "^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$");

    private UuidUtils() {
    }

    public static boolean isUuidV4(String value) {
        return value != null && UUID_V4.matcher(value).matches();
    }

    /** Accepts any RFC-4122 UUID; used for request ids supplied by clients. */
    public static boolean isUuid(String value) {
        if (value == null || value.length() != 36) {
            return false;
        }
        try {
            UUID.fromString(value);
            return true;
        } catch (IllegalArgumentException ex) {
            return false;
        }
    }

    /** Normalises a validated UUID to lower case so hashing is case-insensitive. */
    public static String normalize(String value) {
        return value.toLowerCase(Locale.ROOT);
    }

    public static String newUuidV4() {
        return UUID.randomUUID().toString();
    }
}
